INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"0ec7b4b8-080d-53e2-b94d-f41b3f8b44f7","title":"Life Orientation · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 12","questions":[{"question":"Before accepting a job, what should a learner clarify?","options":["Only the colour of the office","Whether the employer avoids every written record","Duties, pay, hours, conditions and the legitimacy of the employer","Whether friends like the logo"],"correct_index":2,"explanation":"Read and understand employment terms and verify the opportunity. Seek qualified help if terms are unclear or concerning.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is a sound response to a request to falsify a workplace record?","options":["Change it because instructions remove responsibility","Refuse falsification and seek appropriate guidance or reporting support","Delete all evidence immediately","Ask a friend to invent the details"],"correct_index":1,"explanation":"Honesty and accountability apply even under pressure. Use suitable procedures and support while considering personal safety and context.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What belongs on an honest entry-level CV?","options":["Relevant education, skills and experience described accurately","Invented qualifications","Another person's achievements","A guaranteed salary demand presented as a qualification"],"correct_index":0,"explanation":"School projects, volunteering and responsibilities can provide relevant evidence. Describe actual contributions and obtain permission for references where appropriate.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A learner loses marks despite knowing the content. What should they review?","options":["Only handwriting colour","Instruction words, time allocation and how answers address the question","Assume every marker is unfair","Stop practising questions"],"correct_index":1,"explanation":"Exam technique complements knowledge. Practise interpreting commands, structuring answers and allocating time, then use feedback to improve.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A learner has one university application and no confirmed funding. Which revised plan best manages uncertainty?","options":["Assume application automatically guarantees admission and funding.","Use one deadline for every institution and bursary.","Add suitable alternative study or training pathways and track separate admission and funding requirements.","Wait until all opportunities close before reviewing options."],"correct_index":2,"explanation":"Admission and funding are separate, uncertain processes. Realistic alternatives, verified requirements and distinct deadlines reduce the risk of having no workable post-school option.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lo"],"metadata":{"term":2,"focus":"Mixed revision: Workplace choices, contracts and ethics; Post-school planning and exam preparation","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"5cf22e45-5d88-59dc-bf7b-3bda39c54075","title":"Life Orientation · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 12","questions":[{"question":"A news post shows a dramatic claim without a date or source. What should a learner do before sharing?","options":["Share because the headline is emotional","Verify the original source, date, context and supporting evidence","Assume every image is current","Replace verification with the number of likes"],"correct_index":1,"explanation":"Media literacy includes source evaluation and context. Old or altered material can mislead even when it appears convincing.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"How can media representation reinforce stereotypes?","options":["Repeated narrow portrayals can make unfair generalisations seem normal","Every repeated portrayal is automatically accurate","Only written media influences perceptions","Representation has no effect on audiences"],"correct_index":0,"explanation":"Analyse whose voices appear, who is omitted and how groups are framed. Compare portrayals with varied evidence and lived experiences.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What belongs on an honest entry-level CV?","options":["Relevant education, skills and experience described accurately","Invented qualifications","Another person's achievements","A guaranteed salary demand presented as a qualification"],"correct_index":0,"explanation":"School projects, volunteering and responsibilities can provide relevant evidence. Describe actual contributions and obtain permission for references where appropriate.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A learner loses marks despite knowing the content. What should they review?","options":["Only handwriting colour","Instruction words, time allocation and how answers address the question","Assume every marker is unfair","Stop practising questions"],"correct_index":1,"explanation":"Exam technique complements knowledge. Practise interpreting commands, structuring answers and allocating time, then use feedback to improve.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A learner has one university application and no confirmed funding. Which revised plan best manages uncertainty?","options":["Assume application automatically guarantees admission and funding.","Use one deadline for every institution and bursary.","Add suitable alternative study or training pathways and track separate admission and funding requirements.","Wait until all opportunities close before reviewing options."],"correct_index":2,"explanation":"Admission and funding are separate, uncertain processes. Realistic alternatives, verified requirements and distinct deadlines reduce the risk of having no workable post-school option.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lo"],"metadata":{"term":3,"focus":"Mixed revision: Media literacy, rights and civic participation; Post-school planning and exam preparation","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"4b466a79-eaac-52e1-9ca0-8474b9cad3b2","title":"Life Orientation · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 12","questions":[{"question":"A news post shows a dramatic claim without a date or source. What should a learner do before sharing?","options":["Share because the headline is emotional","Verify the original source, date, context and supporting evidence","Assume every image is current","Replace verification with the number of likes"],"correct_index":1,"explanation":"Media literacy includes source evaluation and context. Old or altered material can mislead even when it appears convincing.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"How can media representation reinforce stereotypes?","options":["Repeated narrow portrayals can make unfair generalisations seem normal","Every repeated portrayal is automatically accurate","Only written media influences perceptions","Representation has no effect on audiences"],"correct_index":0,"explanation":"Analyse whose voices appear, who is omitted and how groups are framed. Compare portrayals with varied evidence and lived experiences.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why is equity different from treating everyone identically?","options":["Equity means ignoring discrimination","Equity requires identical support regardless of need","Equity removes all performance expectations","Fair access may require addressing different barriers and support needs"],"correct_index":3,"explanation":"Equity focuses on fair opportunity and participation, which may involve targeted support or accommodation.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A worker notices a safety hazard outside their training. What is the responsible response?","options":["Report it through appropriate channels and avoid unsafe untrained action","Try a dangerous repair alone","Hide it to appear efficient","Encourage others to ignore it"],"correct_index":0,"explanation":"Safety includes recognising limits, following procedures and alerting responsible people. Work ethic does not require taking avoidable risks.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A learner receives a job offer that omits hours and duties but demands an immediate unexplained payment. What is the strongest next step?","options":["Pay immediately because urgency proves legitimacy.","Provide false qualifications to secure the position.","Verify the employer and written terms through independent channels before committing or paying.","Ignore missing conditions because a job title is sufficient."],"correct_index":2,"explanation":"Unclear terms and unexplained upfront charges require scrutiny. Independent verification and clear written conditions support an informed decision without treating every offer as automatically genuine.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lo"],"metadata":{"term":4,"focus":"Mixed revision: Media literacy, rights and civic participation; Workplace choices, contracts and ethics","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=dKf4zpe-LJ0%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"45c9799f-224a-5274-96e0-69076e0309cf","title":"English HL · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 12","questions":[{"question":"What is the effect of Lazy in the headline?","options":["It is a neutral measure of motivation","It proves every learner's attitude","It supplies a transport timetable","It frames learners negatively before their circumstances are examined"],"correct_index":3,"explanation":"The loaded label guides judgment without establishing motives. Critical reading separates description from evaluation and evidence.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Which headline is more balanced?","options":["All learners refuse to work","Transport never affects attendance","Reading-room attendance raises questions about access","Empty chairs prove laziness"],"correct_index":2,"explanation":"The revised headline identifies the issue without assigning unsupported blame. Balanced wording still allows investigation and criticism.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"What does impatient attribute to the train?","options":["A measured delay of exactly one hour","A human quality that intensifies urgency","A literal spoken complaint","Proof of mechanical failure"],"correct_index":1,"explanation":"Personification gives the train urgency and energy, contrasting with Noma's pause. The adjective does not establish a technical fault.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which interpretation remains appropriately qualified?","options":["The letter definitely contains a job rejection.","Noma has never travelled before.","The repeated reading and backward movement suggest uncertainty about departing.","The other travellers know the letter's contents."],"correct_index":2,"explanation":"The text supports hesitation but does not reveal the letter's content or full history. A defensible argument respects those limits.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which evaluation best explains the effect of the train's urgency beside Noma's retreat?","options":["It proves the letter orders Noma to leave the country.","It establishes that the train is literally conscious.","The contrast intensifies tension between outward movement and her apparent hesitation.","It proves Noma will never travel again."],"correct_index":2,"explanation":"Impatient gives the train human urgency, while Noma steps away as others advance. The contrast supports tension and hesitation without revealing the letter or her eventual decision.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","enhl"],"metadata":{"term":2,"focus":"Mixed revision: Framing, omission and persuasive revision; Close reading and literary argument","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8be80661-0344-53fd-97b3-fa8671157547","title":"English HL · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 12","questions":[{"question":"What is the main weakness in the newsletter's causal claim?","options":["A higher pass rate can never be measured","Tutoring cannot possibly help anyone","Other changes may also explain the higher pass rate","Newsletters contain no useful information"],"correct_index":2,"explanation":"Without an appropriate comparison, concurrent changes make it difficult to isolate tutoring's effect. This limits the causal claim without proving the programme ineffective.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Which additional evidence would most strengthen evaluation?","options":["A second slogan praising the programme","A well-designed comparison accounting for class size and learner differences","More copies of the same newsletter","A promise to avoid collecting data"],"correct_index":1,"explanation":"Comparable groups and attention to alternative explanations help test the claim. No single method removes every limitation, so assess design quality.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"What does impatient attribute to the train?","options":["A measured delay of exactly one hour","A human quality that intensifies urgency","A literal spoken complaint","Proof of mechanical failure"],"correct_index":1,"explanation":"Personification gives the train urgency and energy, contrasting with Noma's pause. The adjective does not establish a technical fault.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which interpretation remains appropriately qualified?","options":["The letter definitely contains a job rejection.","Noma has never travelled before.","The repeated reading and backward movement suggest uncertainty about departing.","The other travellers know the letter's contents."],"correct_index":2,"explanation":"The text supports hesitation but does not reveal the letter's content or full history. A defensible argument respects those limits.","stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which evaluation best explains the effect of the train's urgency beside Noma's retreat?","options":["It proves the letter orders Noma to leave the country.","It establishes that the train is literally conscious.","The contrast intensifies tension between outward movement and her apparent hesitation.","It proves Noma will never travel again."],"correct_index":2,"explanation":"Impatient gives the train human urgency, while Noma steps away as others advance. The contrast supports tension and hesitation without revealing the letter or her eventual decision.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"At the station, Noma unfolded the letter once more. The train arrived, impatient and bright. She put the letter in her pocket and stepped away from the platform's edge, while everyone else moved forward."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","enhl"],"metadata":{"term":3,"focus":"Mixed revision: Evaluating evidence and qualified conclusions; Close reading and literary argument","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"134d534f-6e44-53a9-bc7e-db4177d7a0cd","title":"English HL · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 12","questions":[{"question":"What is the main weakness in the newsletter's causal claim?","options":["A higher pass rate can never be measured","Tutoring cannot possibly help anyone","Other changes may also explain the higher pass rate","Newsletters contain no useful information"],"correct_index":2,"explanation":"Without an appropriate comparison, concurrent changes make it difficult to isolate tutoring's effect. This limits the causal claim without proving the programme ineffective.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Which additional evidence would most strengthen evaluation?","options":["A second slogan praising the programme","A well-designed comparison accounting for class size and learner differences","More copies of the same newsletter","A promise to avoid collecting data"],"correct_index":1,"explanation":"Comparable groups and attention to alternative explanations help test the claim. No single method removes every limitation, so assess design quality.","stimulus":"After a school introduced evening tutoring, its pass rate rose. The newsletter credited the programme. However, the year also saw smaller classes and a change in the learners enrolled. The report did not compare similar groups.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Why does the photograph's timing matter?","options":["It may misleadingly suggest low attendance during operating hours","Any photograph proves the headline","Timing never affects visual evidence","It makes interviews unnecessary"],"correct_index":0,"explanation":"A pre-opening image is not reliable evidence of attendance while the room operates. Captions and context affect interpretation.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Which omission most directly weakens the article's explanation?","options":["The brand of every chair","Learners' accounts of transport barriers","The writer's favourite novel","The room's wall colour"],"correct_index":1,"explanation":"Excluding relevant affected voices can narrow an explanation and conceal practical constraints. The omission matters because it relates directly to attendance.","stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Would changing Lazy to absent fully repair the article's fairness? Choose the strongest evaluation.","options":["Yes; replacing one word fixes every evidential problem.","No; the learners' transport accounts are irrelevant.","No; the misleading photograph and missing transport accounts would still need correction.","Yes; photographs never need context."],"correct_index":2,"explanation":"A less judgemental word reduces loaded framing, but accuracy also depends on representative evidence and image context. The article's problems are connected but not identical.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"The headline read: Lazy learners abandon the reading room. The article mentioned empty chairs but omitted interviews with learners who lacked evening transport. Its photograph showed a half-empty room taken before opening time."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","enhl"],"metadata":{"term":4,"focus":"Mixed revision: Evaluating evidence and qualified conclusions; Framing, omission and persuasive revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=DyjByGE3HzY%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"bf9c6fda-77f1-5475-8f07-be872a8375f0","title":"Afrikaans HL · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 12","questions":[{"question":"Wat is die effek van Lui in die opskrif?","options":["Dit raam die leerders negatief voordat hul omstandighede ondersoek is","Dit is 'n neutrale meting","Dit bewys elke leerder se motief","Dit gee vervoerdata"],"correct_index":0,"explanation":"Die gelaaide woord stuur die leser se oordeel sonder voldoende bewys van die leerders se redes.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Watter opskrif is meer gebalanseerd?","options":["Alle leerders weier om te werk","Vervoer beïnvloed nooit bywoning nie","Leë stoele bewys luiheid","Leeslokaal se bywoning laat vrae oor toegang ontstaan"],"correct_index":3,"explanation":"Die herskrywing identifiseer 'n ondersoekbare probleem sonder om ongegronde blaam toe te ken.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Watter beeldspraak bevat die beskrywing van die trein as ongeduldig?","options":["Klanknabootsing","Letterlike verslag van 'n gesprek","Personifikasie","Rym"],"correct_index":2,"explanation":"Die trein kry 'n menslike eienskap, wat dringendheid skep en met Noma se huiwering kontrasteer.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Watter interpretasie bly binne die teks se perke?","options":["Die brief bevat beslis 'n werksafwysing.","Noma het nog nooit gereis nie.","Al die reisigers ken die brief se inhoud.","Die herlees en terugtree suggereer onsekerheid oor vertrek."],"correct_index":3,"explanation":"Die teks gee leidrade van huiwering, maar verklap nie die brief se inhoud of Noma se hele geskiedenis nie.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Hoe werk die trein se ongeduld saam met Noma se terugtree?","options":["Dit bewys dat die brief haar beveel om die land te verlaat.","Dit wys dat die trein letterlik kan dink.","Die teenstelling versterk spanning tussen voortbeweging en haar moontlike huiwering.","Dit bewys dat Noma nooit weer sal reis nie."],"correct_index":2,"explanation":"Die personifikasie skep dringendheid, terwyl Noma teen die groep se beweging optree. Dit ondersteun spanning sonder om die brief se inhoud of haar uiteindelike besluit bekend te maak.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","afhl"],"metadata":{"term":2,"focus":"Mixed revision: Woordkeuse, weglating en visuele konteks; Literêre argument en noukeurige lees","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"0447afae-ffa8-5b77-904f-ef49163f1f69","title":"Afrikaans HL · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 12","questions":[{"question":"Wat verswak die nuusbrief se oorsaaklike aanspraak?","options":["Slaagsyfers kan nooit gemeet word nie","Ekstra onderrig kan niemand help nie","Nuusbriewe bevat nooit feite nie","Ander veranderings kan ook die styging help verklaar"],"correct_index":3,"explanation":"Sonder 'n gepaste vergelyking is dit moeilik om die program se afsonderlike invloed te bepaal.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Watter ondersoek sal die evaluering versterk?","options":["Nog kopieë van dieselfde slagspreuk","Slegs 'n groter foto","'n Goed ontwerpte vergelyking wat ander verskille in ag neem","Die uitsluiting van alle data"],"correct_index":2,"explanation":"Vergelykbare groepe en aandag aan alternatiewe verklarings help om die aanspraak te toets.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Watter beeldspraak bevat die beskrywing van die trein as ongeduldig?","options":["Klanknabootsing","Letterlike verslag van 'n gesprek","Personifikasie","Rym"],"correct_index":2,"explanation":"Die trein kry 'n menslike eienskap, wat dringendheid skep en met Noma se huiwering kontrasteer.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Watter interpretasie bly binne die teks se perke?","options":["Die brief bevat beslis 'n werksafwysing.","Noma het nog nooit gereis nie.","Al die reisigers ken die brief se inhoud.","Die herlees en terugtree suggereer onsekerheid oor vertrek."],"correct_index":3,"explanation":"Die teks gee leidrade van huiwering, maar verklap nie die brief se inhoud of Noma se hele geskiedenis nie.","stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Hoe werk die trein se ongeduld saam met Noma se terugtree?","options":["Dit bewys dat die brief haar beveel om die land te verlaat.","Dit wys dat die trein letterlik kan dink.","Die teenstelling versterk spanning tussen voortbeweging en haar moontlike huiwering.","Dit bewys dat Noma nooit weer sal reis nie."],"correct_index":2,"explanation":"Die personifikasie skep dringendheid, terwyl Noma teen die groep se beweging optree. Dit ondersteun spanning sonder om die brief se inhoud of haar uiteindelike besluit bekend te maak.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"By die stasie vou Noma die brief weer oop. Die trein kom aan, ongeduldig en helder. Sy steek die brief in haar sak en tree terug van die perron se rand terwyl die ander vorentoe beweeg."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","afhl"],"metadata":{"term":3,"focus":"Mixed revision: Bewyse en gekwalifiseerde gevolgtrekkings; Literêre argument en noukeurige lees","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"3ff5d083-e6f0-5b61-9acf-61603f41d2ad","title":"Afrikaans HL · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 12","questions":[{"question":"Wat verswak die nuusbrief se oorsaaklike aanspraak?","options":["Slaagsyfers kan nooit gemeet word nie","Ekstra onderrig kan niemand help nie","Nuusbriewe bevat nooit feite nie","Ander veranderings kan ook die styging help verklaar"],"correct_index":3,"explanation":"Sonder 'n gepaste vergelyking is dit moeilik om die program se afsonderlike invloed te bepaal.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Watter ondersoek sal die evaluering versterk?","options":["Nog kopieë van dieselfde slagspreuk","Slegs 'n groter foto","'n Goed ontwerpte vergelyking wat ander verskille in ag neem","Die uitsluiting van alle data"],"correct_index":2,"explanation":"Vergelykbare groepe en aandag aan alternatiewe verklarings help om die aanspraak te toets.","stimulus":"Nadat aandklasse begin het, styg 'n skool se slaagsyfer. Die nuusbrief skryf die styging aan die program toe. Klasse was egter ook kleiner en die leerdergroep het verander. Geen soortgelyke groepe is vergelyk nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Waarom is die foto se tydstip belangrik?","options":["Elke foto bewys die opskrif","Dit kan 'n misleidende indruk van bywoning gedurende oop ure skep","Tyd maak nooit saak nie","Dit vervang alle onderhoude"],"correct_index":1,"explanation":"'n Foto voor openingstyd toon nie noodwendig gebruik tydens bedryfsure nie. Konteks verander die interpretasie.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Watter weglating verswak die verklaring die meeste?","options":["Die stoele se handelsmerk","Die joernalis se gunstelingkleur","Leerders se verduidelikings van vervoerprobleme","Die muur se verfkode"],"correct_index":2,"explanation":"Die weglating hou direk verband met toegang en laat relevante ervarings buite die verklaring.","stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Sal die vervanging van Lui met afwesige die hele berig regstel?","options":["Ja; een woord herstel elke probleem met die bewyse.","Nee; vervoer kan nooit toegang beïnvloed nie.","Nee; die foto se konteks en die ontbrekende vervoerperspektiewe moet ook herstel word.","Ja; foto's benodig geen tydsverband nie."],"correct_index":2,"explanation":"Minder veroordelende taal verbeter die raamwerk, maar die misleidende foto en weggelate verklarings bly probleme. Billikheid vereis ook akkurate konteks en relevante perspektiewe.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Die opskrif lui: Lui leerders vermy leeslokaal. Die berig noem leë stoele, maar laat gesprekke met leerders sonder aandvervoer weg. Die foto is voor openingstyd geneem."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","afhl"],"metadata":{"term":4,"focus":"Mixed revision: Bewyse en gekwalifiseerde gevolgtrekkings; Woordkeuse, weglating en visuele konteks","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=F_rQwUSTKoQ%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"18fc14c5-e9da-5320-901c-3e249f87b4c1","title":"isiXhosa HL · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"isiXhosa HL","grade":"Grade 12","questions":[{"question":"Liliphi ifuthe legama abangamavila?","options":["Linika umlinganiselo ocacileyo wexesha.","Likhokela isigwebo esibi ngaphambi kokuhlolwa kweemeko.","Liqinisekisa ukuba wonke umfundi uyaxoka.","Lichaza indawo yethala kuphela."],"correct_index":1,"explanation":"Igama linomthwalo wovakalelo kwaye libeka ityala ngaphandle kobungqina obaneleyo bezizathu zabafundi.","stimulus":"Isihloko sithi: Abafundi abangamavila abalisebenzisi ithala. Ifoto yezitulo ezingenabantu yathathwa ngaphambi kokuvulwa. Ingxelo ayiquki amazwi abafundi abangenazithuthi emva kwemini.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Sesiphi isihloko esilungelelanisiweyo?","options":["Ukusetyenziswa kwethala kuvusa imibuzo ngokufikelela.","Bonke abafundi bayakwala ukufunda.","Izitulo ezingenabantu zingqina ubuvila.","Ukuthutha akuchaphazeli mntu."],"correct_index":0,"explanation":"Isihloko sikhomba umba onokuphandwa ngaphandle kokugweba abantu ngezizathu ezingekahlolwa.","stimulus":"Isihloko sithi: Abafundi abangamavila abalisebenzisi ithala. Ifoto yezitulo ezingenabantu yathathwa ngaphambi kokuvulwa. Ingxelo ayiquki amazwi abafundi abangenazithuthi emva kwemini.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Ukuchaza uloliwe njengongxamileyo ngumzekelo wantoni?","options":["Weresiphi","Woluhlu lwamaxabiso","Wemiyalelo yokwakha","Wesimntwiso"],"correct_index":3,"explanation":"Uloliwe unikwa uphawu oluqhele ukunxulunyaniswa nomntu. Oku kunokwenza indawo ivakale icinezela okanye ingxamile.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Sesiphi isigqibo esigcina umda wesicatshulwa?","options":["Ukuvula ileta kwakhona nokubuya umva kunokubonisa ukungaqiniseki ngokuhamba.","Ileta ngokuqinisekileyo iyamgxotha emsebenzini.","UNoma akazange akhwele uloliwe.","Wonke umntu uyawazi umxholo weleta."],"correct_index":0,"explanation":"Isicatshulwa sinika imikhondo yezenzo, kodwa asisixeleli umxholo weleta okanye yonke imbali yomlinganiswa.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Yintoni eyenziwa kukungxama kukaloliwe xa kuthelekiswa nokubuya umva kukaNoma?","options":["Kungqina umxholo opheleleyo weleta.","Kubonisa ukuba uloliwe ngumntu wokwenene.","Kwandisa ingxwabangxwaba phakathi kokuhamba nokungaqiniseki kwakhe.","Kungqina ukuba akasoze ahambe ebomini."],"correct_index":2,"explanation":"Isimntwiso sikaloliwe senza ukuhamba kuvakale kungxamile. Isenzo sikaNoma esichaseneyo sakha ingxwabangxwaba, kodwa asisiniki isigqibo sakhe sokugqibela.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","xhhl"],"metadata":{"term":2,"focus":"Mixed revision: Ukukhethwa kwamagama nokushiywa kolwazi; Uhlalutyo loncwadi olusondele kumbhalo","language":"xh","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=sJ87UYZMguI%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=sJ87UYZMguI%3d&tabid=3205&portalid=0&mid=10756"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c1a5ee27-34cd-5ce2-a95c-4c5ffd9a0431","title":"isiXhosa HL · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"isiXhosa HL","grade":"Grade 12","questions":[{"question":"Leliphi ibango elifuna ukuhlolwa?","options":["Iiyure ezinde kuphela zibangele ukwanda.","Ingxelo ichaza ukwanda nge-20%.","Kwangeniswa iincwadi ezintsha.","Kwaqalwa iklabhu yokufunda."],"correct_index":0,"explanation":"Zininzi izinto ezitshintshileyo ngaxeshanye. Ukubona ukwanda emva kotshintsho akungqini ukuba yinto enye kuphela ebangeleyo.","stimulus":"Ingxelo ithi ukusetyenziswa kwethala kunyuke nge-20% emva kokwandiswa kweeyure. Kwangelo xesha kwangeniswa iincwadi ezintsha kwaza kwaqalwa iklabhu yokufunda. Ingxelo ithi iiyure ezinde kuphela zenze olu tshintsho.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Igama kuphela linegalelo lini kwibango?","options":["Libonisa ukungaqiniseki okufanelekileyo.","Lithetha ukuba kukho izizathu ezininzi.","Lisusa naluphi na uthelekiso.","Lenza ibango lobangela libe ngqongqo kakhulu."],"correct_index":3,"explanation":"Kuphela likhupha ezinye iinkcazelo. Elo bango lifuna ubungqina obomeleleyo bokwahlula ifuthe lezinye izinto.","stimulus":"Ingxelo ithi ukusetyenziswa kwethala kunyuke nge-20% emva kokwandiswa kweeyure. Kwangelo xesha kwangeniswa iincwadi ezintsha kwaza kwaqalwa iklabhu yokufunda. Ingxelo ithi iiyure ezinde kuphela zenze olu tshintsho.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Ukuchaza uloliwe njengongxamileyo ngumzekelo wantoni?","options":["Weresiphi","Woluhlu lwamaxabiso","Wemiyalelo yokwakha","Wesimntwiso"],"correct_index":3,"explanation":"Uloliwe unikwa uphawu oluqhele ukunxulunyaniswa nomntu. Oku kunokwenza indawo ivakale icinezela okanye ingxamile.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Sesiphi isigqibo esigcina umda wesicatshulwa?","options":["Ukuvula ileta kwakhona nokubuya umva kunokubonisa ukungaqiniseki ngokuhamba.","Ileta ngokuqinisekileyo iyamgxotha emsebenzini.","UNoma akazange akhwele uloliwe.","Wonke umntu uyawazi umxholo weleta."],"correct_index":0,"explanation":"Isicatshulwa sinika imikhondo yezenzo, kodwa asisixeleli umxholo weleta okanye yonke imbali yomlinganiswa.","stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Yintoni eyenziwa kukungxama kukaloliwe xa kuthelekiswa nokubuya umva kukaNoma?","options":["Kungqina umxholo opheleleyo weleta.","Kubonisa ukuba uloliwe ngumntu wokwenene.","Kwandisa ingxwabangxwaba phakathi kokuhamba nokungaqiniseki kwakhe.","Kungqina ukuba akasoze ahambe ebomini."],"correct_index":2,"explanation":"Isimntwiso sikaloliwe senza ukuhamba kuvakale kungxamile. Isenzo sikaNoma esichaseneyo sakha ingxwabangxwaba, kodwa asisiniki isigqibo sakhe sokugqibela.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Esitishini uNoma uvula ileta kwakhona. Uloliwe uyangena, ungxamile kwaye uqaqambile. Ufaka ileta epokothweni abuye umva, ngoxa abanye besiya phambili."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","xhhl"],"metadata":{"term":3,"focus":"Mixed revision: Ubungqina, uthelekiso nezigqibo; Uhlalutyo loncwadi olusondele kumbhalo","language":"xh","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=sJ87UYZMguI%3d&tabid=3205&portalid=0&mid=10756","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"ht